import { test, expect } from '@playwright/test'

/**
 * 富文本详情页回归：文章正文是文件服务相对路径图片（/zhi2-pro/...），
 * 必须补全为完整 URL 才能加载，否则详情页正文整块空白。
 * 部署站点：本地 nginx（http://127.0.0.1:8095），数据走真实接口。
 */
const DETAIL_URL = '/#/pages/portal/detail/index?type=article&id=2075391659506978818'

test('文章详情正文图片补全域名并成功加载', async ({ page }) => {
  const imgRequests: string[] = []
  const okImages = new Set<string>()
  page.on('request', req => {
    const url = req.url()
    if (/\.(png|jpe?g|webp|gif)(\?|$)/i.test(url)) imgRequests.push(url)
  })
  page.on('response', async res => {
    try {
      if (/\.(png|jpe?g|webp|gif)(\?|$)/i.test(res.url()) && res.status() === 200) okImages.add(res.url())
    } catch { /* ignore */ }
  })

  await page.goto(`http://127.0.0.1:8095${DETAIL_URL}`, { waitUntil: 'networkidle' })
  await expect(page.getByText('台风避险指南').first()).toBeVisible({ timeout: 15000 })

  const richText = page.locator('uni-rich-text').first()
  await expect(richText).toBeVisible({ timeout: 15000 })

  // 图片节点应使用完整文件服务地址
  const srcs = await richText.locator('img').evaluateAll(nodes => nodes.map(n => n.getAttribute('src')))
  const detailImgs = srcs.filter(s => s && s.includes('/zhi2-pro/'))
  expect(detailImgs.length).toBeGreaterThan(0)
  expect(detailImgs.every(s => s!.startsWith('https://szfweb.szzfcjj.cn:8887/zhi2-pro/'))).toBe(true)

  // 请求日志里不应出现相对路径图片（会落到站点根 404）
  const relativeImageReqs = imgRequests.filter(u => /^http:\/\/127\.0\.0\.1:8095\/zhi2-pro\//.test(u))
  expect(relativeImageReqs.length).toBe(0)

  // 至少一张正文图片网络加载成功
  const loadedDetail = [...okImages].filter(u => u.includes('/zhi2-pro/'))
  expect(loadedDetail.length).toBeGreaterThan(0)
})

