import { test, expect, type Page } from '@playwright/test'

/**
 * 富文本详情页回归：文章正文是文件服务相对路径图片（/zhi2-pro/...），
 * 必须补全为完整 URL 才能加载，否则详情页正文整块空白。
 * 部署站点：本地 nginx（http://127.0.0.1:8095），数据走真实接口。
 * remote 模式需先注入登录 token（缺 token 会静默回退设计稿静态数据）。
 */
const DETAIL_URL = '/#/pages/portal/detail/index?type=article&id=2075391659506978818'
const PROJECT_ID = 'suzhufang'
const ENCRYPTED_PWD = 'H03W0LoMA6EFQZIW46BnNA=='
const TOKEN_KEY = 'flood-token-v1'

async function loginToken(page: Page): Promise<string | null> {
  try {
    const res = await page.request.post('/api/v2.0/security/auth/login', {
      headers: { 'Content-Type': 'application/json', 'zhi-project-id': PROJECT_ID },
      data: { username: 'zsbase', password: ENCRYPTED_PWD },
    })
    if (!res.ok()) return null
    const body = await res.json().catch(() => null) as { code?: number; data?: { accessToken?: string; token?: string } } | null
    return body?.data?.accessToken ?? body?.data?.token ?? null
  } catch {
    return null
  }
}

test('文章详情正文图片补全域名并成功加载', async ({ page }) => {
  const token = await loginToken(page)
  expect(token, '登录接口应返回 token').toBeTruthy()
  await page.addInitScript(([k, v]) => {
    try { window.localStorage.setItem(k as string, v as string) } catch { /* ignore */ }
  }, [TOKEN_KEY, token!] as const)

await page.goto('http://127.0.0.1:8095/', { waitUntil: 'networkidle' })

// 从首页「新闻公告」区块点击首条文章进入详情（与真实用户路径一致）
await expect(page.getByText('新闻公告').first()).toBeVisible({ timeout: 20000 })
const newsSection = page.locator('uni-view', { hasText: '新闻公告' })
const firstNews = page.locator('[class*="news"] >> text=推进').first()
if (await firstNews.count()) {
  await firstNews.click()
} else {
  // 兜底：点「新闻公告」下方第一条带阅读数的卡片
  await page.getByText(/阅读$/).first().click()
}

const richText = page.locator('uni-rich-text').first()
await expect(richText).toBeVisible({ timeout: 20000 })

await page.goto('http://127.0.0.1:8095/', { waitUntil: 'networkidle' })

// 进入「新闻公告」列表页（真实接口），再打开目标文章：正文为多张相对路径图片
await page.goto('http://127.0.0.1:8095/#/pages/portal/list/index?type=news', { waitUntil: 'networkidle' })
const card = page.locator('.article-card', { hasText: '台风避险指南' }).first()
const cardCount = await card.count()
if (cardCount > 0) {
  await card.click()
} else {
  // 目标文章不在首屏第一页时，直接调用路由打开（详情页支持无需列表缓存的真实 id）
  await page.goto('http://127.0.0.1:8095/#/pages/portal/detail/index?type=article&id=2075391659506978818', { waitUntil: 'networkidle' })
}

const richText = page.locator('uni-rich-text').first()
await expect(richText).toBeVisible({ timeout: 20000 })

