import { test, expect, type Page } from '@playwright/test'

const PROJECT_ID = 'suzhufang'
const ENCRYPTED_PWD = 'H03W0LoMA6EFQZIW46BnNA=='
const TOKEN_KEY = 'flood-token-v1'

async function loginToken(page: Page): Promise<string | null> {
  const res = await page.request.post('/api/v2.0/security/auth/login', {
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': PROJECT_ID },
    data: { username: 'zsbase', password: ENCRYPTED_PWD },
  })
  console.log('login status', res.status())
  const body = await res.json().catch(() => null) as { code?: number; data?: { accessToken?: string; token?: string } } | null
  console.log('login code', body?.code, 'token?', Boolean(body?.data))
  return body?.data?.accessToken ?? body?.data?.token ?? null
}

test('诊断详情页数据来源', async ({ page }) => {
  const token = await loginToken(page)
  expect(token).toBeTruthy()
  await page.addInitScript(([k, v]) => { try { window.localStorage.setItem(k as string, v as string) } catch { /* ignore */ } }, [TOKEN_KEY, token!] as const)

  page.on('response', async res => {
    const u = res.url()
    if (u.includes('/article/richText/')) console.log('DETAIL RESP', res.status(), u)
  })
  page.on('requestfailed', req => { if (req.url().includes('/article/')) console.log('FAILED', req.url(), req.failure()?.errorText) })

  await page.goto('http://127.0.0.1:8095/', { waitUntil: 'networkidle' })
  await expect(page.getByText('学习园地').first()).toBeVisible({ timeout: 20000 })
  console.log('TOKEN in storage', await page.evaluate(k => window.localStorage.getItem(k), TOKEN_KEY).then(v => Boolean(v)))
  await page.evaluate(() => { window.location.hash = '#/pages/portal/detail/index?type=article&id=2075391659506978818' })
  await page.waitForTimeout(6000)
  const title = await page.locator('.detail-title').first().innerText().catch(() => 'NA')
  console.log('DETAIL TITLE', JSON.stringify(title))
  const html = await page.locator('uni-rich-text').first().innerHTML().catch(() => 'NA')
  console.log('RICHTEXT snippet', html.slice(0, 300))
})

